                                                columns.RelativeColumn(1.3f);
                                                columns.RelativeColumn(1.3f);
                                                columns.RelativeColumn(1.3f);
                                            }
                                        );


                                        // --------------------------
                                        // Table Header
                                        // --------------------------

                                        table.Header(header =>
                                        {
                                            header.Cell()
                                                .Border(1)
                                                .Padding(7)
                                                .AlignCenter()
                                                .Text("رقم التسجيل")
                                                .Bold();


                                            header.Cell()
                                                .Border(1)
                                                .Padding(7)
                                                .AlignCenter()
                                                .Text("المتدرب")
                                                .Bold();


                                            header.Cell()
                                                .Border(1)
                                                .Padding(7)
                                                .AlignCenter()
                                                .Text("الدفعة")
                                                .Bold();


                                            header.Cell()
                                                .Border(1)
                                                .Padding(7)
                                                .AlignCenter()
                                                .Text("المستوى التقني")
                                                .Bold();


                                            header.Cell()
                                                .Border(1)
                                                .Padding(7)
                                                .AlignCenter()
                                                .Text("نسبة الحضور")
                                                .Bold();


                                            header.Cell()
                                                .Border(1)
